create function public.report_data(p_project uuid,p_report text,p_from date default null,p_to date default null,p_filters jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path='' as $$ declare result jsonb; begin if not private.member(p_project) then raise exception 'PERMISSION_DENIED'; end if; if p_report='audit_logs' then perform private.assert_finance(p_project); end if;
case p_report
when 'financial_events' then select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from (select e.id,e.event_date,e.description,e.event_type,e.reference_number,e.status,coalesce(sum(case when a.account_type in ('BANK','CASH','WALLET') then case l.direction when 'DEBIT' then l.amount_minor else -l.amount_minor end else 0 end),0)::text cash_movement_minor,(sum(coalesce(sum(case when a.account_type in ('BANK','CASH','WALLET') then case l.direction when 'DEBIT' then l.amount_minor else -l.amount_minor end else 0 end),0)) over(order by e.event_date,e.posted_at,e.id))::text running_balance_minor from public.financial_events e join public.ledger_entries l on l.financial_event_id=e.id join public.financial_accounts a on a.id=l.account_id where e.project_id=p_project group by e.id order by e.event_date,e.posted_at,e.id) r where (p_from is null or r.event_date>=p_from) and (p_to is null or r.event_date<=p_to);
when 'project_members' then select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from (select m.id,p.full_name,m.role,coalesce((select sum(f.amount_minor) from public.purchase_funding_allocations f join public.purchases pu on pu.id=f.purchase_id where f.member_user_id=m.user_id and f.project_id=p_project and pu.status='posted'),0)::text personal_spend_minor,coalesce((select sum(rp.amount_minor) from public.reimbursement_payments rp join public.reimbursement_claims cl on cl.id=rp.reimbursement_claim_id join public.financial_events fe on fe.id=rp.financial_event_id where cl.claimant_user_id=m.user_id and cl.project_id=p_project and fe.status='POSTED'),0)::text reimbursed_minor,(coalesce(-private.account_balance((select id from public.financial_accounts where project_id=p_project and account_type='MEMBER_PAYABLE' and owner_user_id=m.user_id)),0))::text reimbursement_outstanding_minor,(coalesce(private.account_balance((select id from public.financial_accounts where project_id=p_project and account_type='ADVANCE' and owner_user_id=m.user_id)),0))::text advance_outstanding_minor from public.project_members m join public.profiles p on p.id=m.user_id where m.project_id=p_project) r;
when 'reimbursement_claims' then select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from (select c.id,p.full_name,c.status,c.requested_minor::text,c.approved_minor::text,coalesce(sum(case when e.status='POSTED' then rp.amount_minor else 0 end),0)::text paid_minor,private.claim_balance(c.id)::text remaining_minor,(c.approved_minor-coalesce(sum(case when e.status='POSTED' then rp.amount_minor else 0 end),0)-private.claim_balance(c.id))::text refund_adjustment_minor from public.reimbursement_claims c join public.profiles p on p.id=c.claimant_user_id left join public.reimbursement_payments rp on rp.reimbursement_claim_id=c.id left join public.financial_events e on e.id=rp.financial_event_id where c.project_id=p_project group by c.id,p.full_name) r;
when 'bills' then select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from (select b.id,v.name vendor,b.invoice_number,b.issue_date,b.due_date,b.total_minor::text,private.bill_balance(b.id)::text outstanding_minor,case when private.bill_balance(b.id)>0 and b.due_date<current_date then 'overdue' else b.status end status from public.bills b left join public.vendors v on v.id=b.vendor_id where b.project_id=p_project and (p_from is null or b.issue_date>=p_from) and (p_to is null or b.issue_date<=p_to)) r;
when 'budget_lines' then select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from (
select x.*, (planned_minor::bigint-actual_minor::bigint-committed_minor::bigint)::text remaining_minor,
case when planned_minor::bigint=0 then 0 else round(actual_minor::numeric*100/planned_minor::numeric,2) end utilization_percent
from (select bl.id,b.name budget,b.start_date,b.end_date,c.name category,bl.planned_minor::text,
coalesce((select sum(case le.direction when 'DEBIT' then le.amount_minor else -le.amount_minor end) from public.ledger_entries le join public.financial_accounts a on a.id=le.account_id join public.financial_events fe on fe.id=le.financial_event_id where le.project_id=p_project and le.category_id=bl.category_id and a.account_type='EXPENSE' and fe.event_date between b.start_date and b.end_date),0)::text actual_minor,
coalesce((select sum(private.request_remaining(r.id)) from public.purchase_requests r where r.project_id=p_project and r.category_id=bl.category_id and r.status='approved'),0)::text committed_minor,
bl.warning_percent,bl.hard_stop from public.budget_lines bl join public.budgets b on b.id=bl.budget_id join public.categories c on c.id=bl.category_id where bl.project_id=p_project) x) r;
when 'vendors' then select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from (
select x.*,(purchases_minor::bigint+bills_minor::bigint-refunds_minor::bigint)::text net_spend_minor from (
select v.id,v.name,v.gstin,
coalesce((select sum(p.total_minor) from public.purchases p where p.vendor_id=v.id and p.status='posted'),0)::text purchases_minor,
coalesce((select sum(b.total_minor) from public.bills b where b.vendor_id=v.id and b.financial_event_id is not null and b.status<>'cancelled'),0)::text bills_minor,
coalesce((select sum(bp.amount_minor) from public.bill_payments bp join public.bills b on b.id=bp.bill_id join public.financial_events e on e.id=bp.financial_event_id where b.vendor_id=v.id and e.status='POSTED'),0)::text bill_payments_minor,
coalesce((select sum(rf.amount_minor) from public.refunds rf left join public.purchases p on p.id=rf.purchase_id left join public.bills b on b.id=rf.bill_id join public.financial_events e on e.id=rf.financial_event_id where coalesce(p.vendor_id,b.vendor_id)=v.id and e.status='POSTED'),0)::text refunds_minor
from public.vendors v where v.project_id=p_project) x) r;
when 'funding_tranches' then select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from (select f.id,f.name,f.type,f.sanctioned_amount_minor::text,coalesce(sum(case when e.status='POSTED' and (p_from is null or t.received_at>=p_from) and (p_to is null or t.received_at<=p_to) then t.amount_minor else 0 end),0)::text received_minor,count(t.id) filter(where e.status='POSTED') tranche_count,min(t.received_at) filter(where e.status='POSTED') first_received,max(t.received_at) filter(where e.status='POSTED') last_received from public.funding_sources f left join public.funding_tranches t on t.funding_source_id=f.id left join public.financial_events e on e.id=t.financial_event_id where f.project_id=p_project group by f.id) r;
when 'purchases' then select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from (
select e.id,e.event_date,e.description,e.event_type,e.status,c.name category,v.name vendor,pr.full_name member,
coalesce((select string_agg(distinct f.source_type,', ') from public.purchase_funding_allocations f where f.purchase_id=pu.id),'BILL') payment_source,
sum(case l.direction when 'DEBIT' then l.amount_minor else -l.amount_minor end)::text total_minor
from public.financial_events e join public.ledger_entries l on l.financial_event_id=e.id join public.financial_accounts a on a.id=l.account_id
left join public.categories c on c.id=l.category_id
left join public.refunds rf on rf.financial_event_id=e.id
left join public.financial_events original on original.id=e.reverses_event_id
left join public.purchases pu on pu.id=coalesce(rf.purchase_id,original.source_id,e.source_id)
left join public.bills bi on bi.id=coalesce(original.source_id,e.source_id)
left join public.vendors v on v.id=coalesce(pu.vendor_id,bi.vendor_id)
left join public.profiles pr on pr.id=pu.purchased_by_user_id
where e.project_id=p_project and a.account_type='EXPENSE' and (p_from is null or e.event_date>=p_from) and (p_to is null or e.event_date<=p_to)
and (coalesce(p_filters->>'category','')='' or l.category_id::text=p_filters->>'category')
and (coalesce(p_filters->>'vendor','')='' or v.id::text=p_filters->>'vendor')
and (coalesce(p_filters->>'member','')='' or exists(select 1 from public.purchase_funding_allocations f where f.purchase_id=pu.id and f.member_user_id::text=p_filters->>'member'))
and (coalesce(p_filters->>'source','')='' or exists(select 1 from public.purchase_funding_allocations f where f.purchase_id=pu.id and f.source_type=p_filters->>'source'))
and (coalesce(p_filters->>'status','')='' or e.status=p_filters->>'status')
group by e.id,c.name,v.name,pr.full_name,pu.id order by e.event_date,e.id) r;
when 'purchase_register' then select coalesce(jsonb_agg(private.safe_json(to_jsonb(r))),'[]') into result from (select p.*,coalesce((select sum(r.amount_minor) from public.refunds r join public.financial_events e on e.id=r.financial_event_id where r.purchase_id=p.id and e.status='POSTED'),0)::text refunds_minor from public.purchases p where p.project_id=p_project and p.status='posted' and (p_from is null or p.purchase_date>=p_from) and (p_to is null or p.purchase_date<=p_to) order by purchase_date,id) r;
when 'assets' then select coalesce(jsonb_agg(private.safe_json(to_jsonb(r))),'[]') into result from public.assets r where project_id=p_project;
when 'audit_logs' then select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from public.audit_logs r where project_id=p_project and (p_from is null or created_at::date>=p_from) and (p_to is null or created_at::date<=p_to);
else raise exception 'INVALID_REPORT'; end case; return result; end $$;
revoke all on function public.report_data(uuid,text,date,date,jsonb) from public;
grant execute on function public.report_data(uuid,text,date,date,jsonb) to authenticated;
